def steps_until_non_decreasing(nums):
    stack=[];answer=0
    for value in nums:
        steps=0
        while stack and value>=stack[-1][0]:steps=max(steps,stack.pop()[1])
        steps=steps+1 if stack else 0
        answer=max(answer,steps);stack.append((value,steps))
    return answer

